/**
 * Collects the FIGURE data of every journal article into
 * src/lib/lifetimes.gen.ts, so the summary page ("what percentage of your
 * life do you spend on everything") is built from the same numbers as the
 * articles themselves. Runs before every build; do not edit the output.
 */
import { readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "src", "routes", "journal");
const LIFE = 79;

const rows = [];
for (const file of (await readdir(dir)).sort()) {
  if (!file.endsWith(".tsx") || file === "index.tsx") continue;
  const src = await readFile(join(dir, file), "utf8");
  const fig = src.match(/const FIGURE: LifeFigureData = (\{[\s\S]*?\n\});/);
  if (!fig) continue;
  const data = new Function(`return ${fig[1]}`)();
  const title =
    src.match(/<PageSEO\s+title="([^"]+)"/)?.[1] ?? src.match(/const TITLE\s*=\s*"([^"]+)"/)?.[1];
  if (!title) throw new Error(`${file}: no PageSEO title`);
  const num = (s) => Number(String(s).replace(/[^\d.]/g, ""));
  const perYear = num(data.toYear.op) || 365;
  const span = num(data.toLife.op);
  const slug = file.replace(/\.tsx$/, "");
  // Sleep is counted in calendar years of a whole life; everything else in
  // waking years (5,840 h), which a 79-year life holds 79 of.
  const sleep = slug.endsWith("-sleeping");
  rows.push({
    slug,
    title,
    hoursPerDay: Math.round(((data.day.hours * perYear) / 365) * 100) / 100,
    years: data.life.years,
    span,
    sleep,
    share: Math.round((data.life.years / LIFE) * 1000) / 10,
  });
}
rows.sort((a, b) => b.years - a.years);

const out = `// Generated by scripts/gen-lifetimes.mjs from each article's FIGURE. Do not edit.
export interface Lifetime {
  slug: string;
  title: string;
  /** Average hours a day across every day of the year. */
  hoursPerDay: number;
  /** Lifetime total in waking years (calendar years for sleep). */
  years: number;
  /** Years the article counts over. */
  span: number;
  sleep: boolean;
  /** Percent of a 79-year life: of all time for sleep, of waking time otherwise. */
  share: number;
}

export const LIFETIMES: Lifetime[] = ${JSON.stringify(rows, null, 2)};
`;
await writeFile(join(root, "src", "lib", "lifetimes.gen.ts"), out);
console.log(`gen-lifetimes: ${rows.length} articles`);
